# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::SnapshotValues do
  # A complete snapshot as parsed JSON carries it.
  def snapshot_values_valid_snapshot
    {
      "id" => 11, "company_id" => 1, "project_id" => 10, "user_id" => 20, "agent_id" => nil,
      "work_date" => "2026-03-02", "duration" => BigDecimal("30.5"), "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => "2026-03-02T09:00:00Z", "updated_at" => "2026-03-02T09:00:00Z"
    }
  end

  def snapshot_values_nested(levels)
    levels.times.reduce("leaf") { |value, _| { "child" => value } }
  end

  # "Check whether a complete correction with source "agent" reaches the outbox despite the consumer rejecting that value."
  it "names only source when it is agent or not an allowed String, and accepts every allowed source" do
    expect(described_class.invalid_fields(snapshot_values_valid_snapshot)).to eq([])

    ["agent", ["manual"], 1, nil, { "name" => "manual" }, "Manual", ""].each do |source|
      expect(described_class.invalid_fields(snapshot_values_valid_snapshot.merge("source" => source)))
        .to eq(["source"]), "expected source #{source.inspect} to be refused"
    end
    %w[manual cli mcp automation import].each do |source|
      expect(described_class.invalid_fields(snapshot_values_valid_snapshot.merge("source" => source))).to eq([])
    end
  end

  # "producers must reject values that stop delivery for everyone"
  it "names each field alone whose value the projection or the relay would refuse" do
    refused = [
      ["bill_status", "paid"], ["bill_status", 1], ["review_status", "done"], ["review_status", 1],
      ["locked", "true"], ["locked", nil], ["duration", -1], ["duration", "30"],
      ["work_date", "2026-02-30"], ["work_date", "not a date"], ["created_at", "yesterday"], ["updated_at", nil],
      ["discarded_at", "x"], ["id", 0], ["id", "11"], ["company_id", -1], ["project_id", 0], ["user_id", "5"],
      ["agent_id", -3], ["agent_id", 0], ["note", 4], ["external_run_id", 7], ["external_session_id", []],
      ["proof_url", 1], ["source_metadata", []], ["source_metadata", nil], ["proof_metadata", "{}"],
      ["duration", Float::INFINITY], ["duration", Float::NAN], ["duration", BigDecimal("Infinity")],
      ["duration", BigDecimal("NaN")]
    ]

    refused.each do |field, value|
      expect(described_class.invalid_fields(snapshot_values_valid_snapshot.merge(field => value)))
        .to eq([field]), "expected #{field} = #{value.inspect} to be refused"
    end
  end

  # "docs/solutions/design-patterns/a-refused-snapshot-stalls-the-relay-so-align-producer-and-skip-ignored-checks.md records why producers must reject values that stop delivery for everyone."
  it "names every field the projection would refuse, not only source" do
    snapshot = snapshot_values_valid_snapshot.merge(
      "project_id" => 0, "user_id" => "6", "agent_id" => -3, "work_date" => "2026-02-30", "duration" => -1,
      "note" => 4, "bill_status" => "paid", "review_status" => 1, "locked" => "true", "source_metadata" => [],
      "external_run_id" => 7, "discarded_at" => "x", "created_at" => "yesterday", "updated_at" => nil
    )

    expect(described_class.invalid_fields(snapshot)).to match_array(
      %w[project_id user_id agent_id work_date duration note bill_status review_status locked source_metadata
         external_run_id discarded_at created_at updated_at]
    )
  end

  # "producers must reject values that stop delivery for everyone"
  it "accepts metadata nested 96 levels and refuses 97, so the relay can still parse what is stored" do
    %w[source_metadata proof_metadata].each do |field|
      expect(described_class.invalid_fields(snapshot_values_valid_snapshot.merge(field => snapshot_values_nested(96))))
        .to eq([])
      expect(described_class.invalid_fields(snapshot_values_valid_snapshot.merge(field => snapshot_values_nested(97))))
        .to eq([field])
    end
  end

  it "refuses very deep and cyclic metadata without exhausting the stack" do
    very_deep = 10_000.times.reduce("leaf") { |value, _| { "child" => [value] } }
    cyclic = {}
    cyclic["child"] = cyclic

    [very_deep, cyclic].each do |metadata|
      expect(described_class.invalid_fields(snapshot_values_valid_snapshot.merge("source_metadata" => metadata)))
        .to eq(["source_metadata"])
    end
  end

  it "accepts the Date, Time and BigDecimal values in-process callers and parsed JSON send" do
    at = Time.zone.parse("2026-03-02 09:00:00")
    snapshot = {
      "id" => 11, "company_id" => 1, "project_id" => 10, "user_id" => 20, "agent_id" => 4,
      "work_date" => Date.new(2026, 3, 2), "duration" => BigDecimal("30.5"), "note" => nil,
      "bill_status" => "billed", "review_status" => "approved", "locked" => true, "source" => "import",
      "source_metadata" => { "rate" => BigDecimal("1.00000000000000000001") }, "external_run_id" => "run",
      "external_session_id" => "session", "proof_url" => "https://example.test/p", "proof_metadata" => {},
      "discarded_at" => at, "created_at" => at, "updated_at" => at
    }

    expect(described_class.invalid_fields(snapshot)).to eq([])
    expect(described_class.invalid_fields(snapshot.merge("duration" => 0, "discarded_at" => "2026-03-02T09:00:00+05:30")))
      .to eq([])
    plain_times = snapshot.merge("duration" => 30.0, "created_at" => Time.utc(2026, 3, 2, 9),
                                 "updated_at" => Time.utc(2026, 3, 2, 9), "discarded_at" => nil)
    expect(described_class.invalid_fields(plain_times)).to eq([])
  end

  # "The base's EntryCommand enforces the allowed sources; this new producer bypasses it."
  # The service deploys without the contracts directory, so this keeps its copy equal to the contract.
  it "keeps its frozen source and status lists equal to the contract's entry_values" do
    values = YAML.safe_load_file(Rails.root.join("../contracts/timekeeping/entry_snapshots.yml")).fetch("entry_values")

    expect(values.fetch("sources")).to eq(%w[manual cli mcp automation import])
    expect(values.fetch("sources")).not_to include("agent")
    expect(described_class::SOURCES).to eq(values.fetch("sources"))
    expect(described_class::BILL_STATUSES).to eq(values.fetch("bill_statuses"))
    expect(described_class::REVIEW_STATUSES).to eq(values.fetch("review_statuses"))
    expect([described_class::SOURCES, described_class::BILL_STATUSES, described_class::REVIEW_STATUSES,
            described_class::RULES]).to all(be_frozen)
    expect(described_class::RULES.keys).to match_array(Timekeeping::OutboxFields::ENTRY_FIELDS - ["version"])
    expect(Timekeeping::EntryCommand::FIELD_SHAPES.fetch("source").call("agent")).to be_falsey
  end

  # Generated by Descant: acceptance tests below.
  it "applies only the rules passed in rules: and all RULES without it" do
    snapshot = snapshot_values_valid_snapshot.merge("locked" => nil, "source" => "agent")

    expect(described_class.invalid_fields(snapshot)).to eq(%w[locked source])
    expect(described_class.invalid_fields(snapshot, rules: described_class::RULES.except("locked"))).to eq(["source"])
    expect(described_class.invalid_fields(snapshot, rules: described_class::RULES.slice("note"))).to eq([])
  end
end
